#!/usr/bin/env python3
from pathlib import Path
import sys, shutil, datetime
root=Path(sys.argv[1] if len(sys.argv)>1 else '/opt/akira')
files={'server/src/profiles.mjs': "export function validAvatar(value) {\n  if (value === null || value === '') return true;\n  if (typeof value !== 'string' || value.length > 200000) return false;\n  return /^data:image\\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(value);\n}\nexport async function profileRoutes(req, path, send, authenticate, pool) {\n  const members = path.match(/^\\/api\\/v1\\/rooms\\/(\\d{1,18})\\/members$/);\n  if (!(path === '/api/v1/profile' && ['GET','POST'].includes(req.method)) && !(members && req.method === 'GET')) return false;\n  try {\n    const user = await authenticate(req.headers.authorization);\n    if (!user) { send(401,{error:'unauthorized'}); return true; }\n    if (members) {\n      const access = await pool().query('SELECT 1 FROM akira_room_members m JOIN akira_rooms r ON r.id=m.room_id WHERE r.public_id=$1 AND m.user_id=$2',[members[1],user.id]);\n      if (!access.rows.length) { send(403,{error:'join_room_first'}); return true; }\n      const {rows} = await pool().query('SELECT u.public_id::text AS id,u.display_name AS name,u.avatar_url AS pic,u.bio,m.role,(u.id=r.owner_id) AS owner FROM akira_room_members m JOIN akira_rooms r ON r.id=m.room_id JOIN akira_users u ON u.id=m.user_id WHERE r.public_id=$1 ORDER BY m.joined_at,u.public_id',[members[1]]);\n      send(200,{members:rows}); return true;\n    }\n    if (req.method === 'POST') {\n      let raw=''; let size=0;\n      for await (const chunk of req) { size+=Buffer.byteLength(chunk); if(size>210000){send(413,{error:'profile_too_large'});return true;} raw+=chunk; }\n      let body; try {body=JSON.parse(raw);} catch {send(400,{error:'invalid_json'});return true;}\n      if (!body || typeof body.name!=='string' || !body.name.trim() || body.name.trim().length>80 || typeof body.bio!=='string' || body.bio.length>500 || !validAvatar(body.pic)) {send(400,{error:'invalid_profile'});return true;}\n      await pool().query('UPDATE akira_users SET display_name=$1,avatar_url=$2,bio=$3,updated_at=now() WHERE id=$4',[body.name.trim(),body.pic||null,body.bio,user.id]);\n    }\n    const {rows}=await pool().query('SELECT public_id::text AS id,display_name AS name,avatar_url AS pic,bio FROM akira_users WHERE id=$1',[user.id]);\n    send(200,{profile:rows[0]});\n  } catch {send(503,{error:'profiles_unavailable'});}\n  return true;\n}\n", 'web/src/profile-app.js': "/* Persist only the signed-in account's public profile. */\n(function(){\n  var saved='',timer;\n  function api(){return AKIRA_API_BASE.replace(/\\/$/,'').replace(/\\/api\\/v1$/,'')+'/api/v1';}\n  function current(){return{id:String(A.id),name:A.name,pic:A.pic||null,bio:A.bio||''};}\n  window.akiraSyncProfile=async function(){\n    var token=akiraToken();if(!token)return;\n    var p=current(),body=JSON.stringify(p),key=token+body;if(key===saved)return;\n    var response=await fetch(api()+'/profile',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:body});\n    if(!response.ok)throw Error('Profile could not sync ('+response.status+'). Please retry.');\n    saved=key;\n    AkiraBridge.toRoom({t:'profile-updated',profile:p});\n  };\n  var originalSave=saveA;\n  saveA=function(){originalSave();clearTimeout(timer);timer=setTimeout(function(){akiraSyncProfile().catch(function(e){toast(e.message)})},400)};\n  var originalOpen=openRoom;\n  openRoom=async function(r){try{await akiraSyncProfile();}catch(e){toast(e.message);return;}return originalOpen(r)};\n  // Supply the current user's identity without clearing active bridge listeners.\n  var bridge=AkiraBridge;\n  window.AkiraBridge=Object.freeze(Object.assign({},bridge,{getContext:function(){var ctx=bridge.getContext();if(ctx)ctx.profile=current();return ctx;}}));\n  var originalOther=otherModel;\n  otherModel=function(u){if(!u.real)return originalOther(u);return{n:u.n,e:'👤',pic:u.pic||null,id:String(u.id),bio:u.bio||'',country:'',age:null,cover:null,ci:0,wl:1,wp:0,cl:1,cp:0,fl:0,fg:0,sent:0,recv:0,sw:{},rw:{},room:'',streak:0,u:u,mine:false};};\n})();\n", 'web/src/profile-room.js': '/* Render server-backed identities; no synthetic members or photos. */\n(function(){\n  var ctx=AkiraBridge.getContext()||{},me=ctx.profile;\n  if(!me)return;\n  var members=[],busy=false,stopped=false;\n  function photo(el,p){el.textContent=\'👤\';if(!p.pic)return;var img=document.createElement(\'img\');img.src=p.pic;img.alt=p.name||p.n||\'Profile\';img.style.cssText=\'width:100%;height:100%;object-fit:cover;border-radius:inherit;display:block\';img.onerror=function(){el.textContent=\'👤\'};el.replaceChildren(img);}\n  function profile(p){if(String(p.id)===String(me.id)){AkiraBridge.toApp({t:\'profile\',u:{seat:0,id:me.id}});return;}AkiraBridge.toApp({t:\'profile\',u:{id:String(p.id),n:p.name,pic:p.pic,bio:p.bio,e:\'👤\',real:true}});}\n  var originalRender=render;\n  render=function(){originalRender();var face=document.querySelector(\'.seat[data-i="0"] .face\');if(face)photo(face,me);var own=members.find(function(p){return String(p.id)===String(me.id)});if(!own||!own.owner){var host=document.getElementById(\'host\');host.querySelectorAll(\'.crown,.tag\').forEach(function(el){el.remove()});}};\n  sid=function(s){return s.id?String(s.id):\'\';};\n  seats.forEach(function(s,i){seats[i]=i===0?{i:0,id:me.id,n:me.name,pic:me.pic,e:\'👤\',muted:myMute,talk:false}:{i:i,empty:1};});\n  U=[];\n  function activeMembers(){\n    if(!akiraVoiceReady||!akiraVoiceRoom)return [me];\n    var ids=new Set([String(me.id)]);akiraVoiceRoom.remoteParticipants.forEach(function(p){ids.add(String(p.identity))});\n    return members.filter(function(p){return ids.has(String(p.id))});\n  }\n  total=function(){return activeMembers().length;};\n  function rows(){var list=document.getElementById(\'real-members\');if(!list)return;var query=document.getElementById(\'real-search\').value.toLowerCase();list.replaceChildren();activeMembers().filter(function(p){return p.name.toLowerCase().includes(query)||String(p.id).includes(query)}).forEach(function(p){var row=document.createElement(\'button\');row.className=\'urow\';row.style.width=\'100%\';var avatar=document.createElement(\'div\');avatar.className=\'ua\';photo(avatar,p);var label=document.createElement(\'div\');label.className=\'un\';var name=document.createElement(\'b\');name.textContent=p.name;var id=document.createElement(\'small\');id.textContent=\'ID \'+p.id+(p.owner?\' · Room owner\':\'\');label.append(name,id);row.append(avatar,label);row.onclick=function(){profile(p)};list.append(row)});}\n  usersSheet=function(){open(\'<h3>Room members</h3><input class="field" id="real-search" placeholder="Search by name or ID"><div class="ul" id="real-members"></div>\');document.getElementById(\'real-search\').oninput=rows;rows();};\n  seatSheet=function(i){if(i===0)profile(me);else toast(\'This seat is empty\');};\n  async function refresh(){if(busy||stopped)return;busy=true;try{var url=ctx.voiceApi.replace(/\\/$/,\'\').replace(/\\/api\\/v1$/,\'\')+\'/api/v1/rooms/\'+encodeURIComponent(ctx.id)+\'/members\';var res=await fetch(url,{headers:{Authorization:\'Bearer \'+ctx.voiceAuth}});if(!res.ok)throw Error(\'Profile list unavailable\');var data=await res.json();if(stopped)return;members=data.members;var mine=members.find(function(p){return String(p.id)===String(me.id)});if(mine){me=mine;Object.assign(seats[0],{n:me.name,pic:me.pic,id:me.id});}render();rows();}catch(e){console.warn(e.message)}finally{busy=false;}}\n  AkiraBridge.onRoom(function(d){if(d.t===\'profile-updated\'){me=d.profile;Object.assign(seats[0],{n:me.name,pic:me.pic});render();refresh();}});\n  render();refresh();var interval=setInterval(refresh,5000);\n  window.addEventListener(\'pagehide\',function(){stopped=true;clearInterval(interval)});\n})();\n'}
changes={}
p=root/'server/src/server.mjs'
s=p.read_text()
if "./profiles.mjs" not in s:
    anchor="  // Mint short-lived, room-scoped LiveKit credentials only for authenticated members."
    assert s.count(anchor)==1, 'Unexpected server code; no files changed'
    s="import { profileRoutes } from './profiles.mjs';\n"+s.replace(anchor,"  if (await profileRoutes(req, url.pathname, send, authenticate, getPool)) return;\n"+anchor)
changes[p]=s
for filename,addon,anchor in [('web/index.html','profile-app.js','<script src="src/app.js"></script>'),('web/room.html','profile-room.js','<script src="src/room.js"></script>')]:
    p=root/filename;s=p.read_text()
    if addon not in s:
        assert s.count(anchor)==1, 'Unexpected HTML; no files changed'
        s=s.replace(anchor,anchor+'\n<script src="src/'+addon+'"></script>')
    changes[p]=s
p=root/'web/src/room.js';s=p.read_text()
s=s.replace('setInterval(botGift,28000);','')
s='\n'.join(line for line in s.split('\n') if not line.startswith('setInterval(function(){var o=others();') and not line.startswith('for(var ui=0;ui<121;ui++)'))
s=s.replace('sys("📢 Welcome to the room! Please behave politely.");msg("Rafi","🧑‍🎤","Greetings to everyone 👋",{ci:1,lv:16});msg("Nusrat","👩‍🦰","Will sing tonight 🎶",{ci:2,lv:19});','sys("Welcome to the room");')
changes[p]=s
for name,content in files.items():changes[root/name]=content
backup=root/'backups'/('profile-fix-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
for p,content in changes.items():
    if p.exists():
        dest=backup/p.relative_to(root);dest.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dest)
    p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
print('PROFILE PATCH INSTALLED; backup:',backup)
